### BaseViewController 내 바텀시트 관련 메소드 추가
기존에 바텀시트의 기능을 하는 클래스에서 불필요하게 똑같은 메소드들이 반복되고 있었습니다. 그래서 각 바텀시트뷰컨이 상속하는 BaseViewController에 해당 메소드를 추가하여 참조해서 사용할 수 있도록 수정하였습니다!
``` Swift
extension BaseViewController {
    
    func presentBottomSheet(
        _ contentView: UIView,
        _ dimmedView: UIView,
        in viewController: UIViewController,
        animated: Bool = true,
        completion: (() -> Void)? = nil
    ) {
        self.modalPresentationStyle = .overFullScreen
        viewController.present(self, animated: false) {
            self.animateBottomSheetPresentation(
                contentView,
                dimmedView,
                animated: animated,
                completion: completion
            )
        }
    }
    
    func dismissBottomSheet(
        _ contentView: UIView,
        _ dimmedView: UIView,
        animated: Bool = true,
        completion: (() -> Void)? = nil
    ) {
        if animated {
            UIView.animate(withDuration: 0.3, delay: 0, options: .curveEaseIn, animations: {
                contentView.transform = CGAffineTransform(translationX: 0, y: ScreenUtils.height / 812 * 642)
                dimmedView.alpha = 0
            }, completion: { _ in
                self.dismiss(animated: false, completion: completion)
            })
        } else {
            dimmedView.alpha = 0
            self.dismiss(animated: false, completion: completion)
        }
    }
    
    private func animateBottomSheetPresentation(
        _ contentView: UIView,
        _ dimmedView: UIView,
        animated: Bool,
        completion: (() -> Void)? = nil
    ) {
        if animated {
            contentView.transform = CGAffineTransform(translationX: 0, y: ScreenUtils.height / 812 * 642)
            dimmedView.alpha = 0
            
            UIView.animate(withDuration: 0.3, delay: 0, options: .curveEaseOut, animations: {
                dimmedView.alpha = 1
                contentView.transform = .identity
            }, completion: { _ in
                completion?()
            })
        } else {
            contentView.alpha = 1
            completion?()
        }
    }
    
}

```

### DRDimmedView 추가
현재 프로젝트에서 dimmedview가 많이 사용되고 있어서 따로 DRDimmedView를 하나 만들어 적용하였습니다
dimmedview를 탭했을 때 별도의 액션 처리가 필요한 경우에는 delegate를 사용해서 처리해두었습니다!

``` Swift
import UIKit

protocol DimmedViewDelegate: AnyObject {
    
    func didTapDimmedView()
    
}

extension DimmedViewDelegate {
    
    func didTapDimmedView() {}
    
}

final class DRDimmedView: BaseView {    
    
    // MARK: - Properties
    
    weak var delegate: DimmedViewDelegate?
    
    
    // MARK: - Life Cycles
    
    override func setStyle() {
        self.do {
            $0.backgroundColor = UIColor(resource: .drBlack).withAlphaComponent(0.4)
            $0.alpha = 0
            let gesture = UITapGestureRecognizer(target: self, action: #selector(didTapDimmedView))
            $0.isUserInteractionEnabled = true
            $0.addGestureRecognizer(gesture)
        }
    }
    
}


// MARK: - @objc Methods

extension DRDimmedView {
    
    @objc
    func didTapDimmedView() {
        delegate?.didTapDimmedView()
    }
    
}
```


